/* 第06轮HTML剪辑台：真实片段状态、串行样例播放，未进行编码或混音。 */
(()=>{
 const C=Cimora,{S,M,E,path,link}=C;createCimoraEditModel(M,S);const T=M.editing;
 const B=(text,a,id='',extra='')=>`<button type="button" class="cm-button ghost" data-edit="${a}" data-id="${E(id)}" ${extra}>${text}</button>`;
 const num=n=>Number(n.toFixed(2)),clock=n=>{const t=Math.round(Math.max(0,n)*10)/10;return C.timecode(t)+'.'+Math.round(t%1*10)},checked=v=>v?'checked':'';
 function current(c){const e=T.ensure(c);return T.rows(c).find(r=>r.id===e.selectedId)||T.rows(c)[0];}
 function sourceOptions(c){return M.production.shots(c.e).flatMap(s=>s.candidates.filter(a=>T.media(a)).map(a=>`<option value="${E(s.id+'|'+a.id)}">${E(s.title)} · v${a.version}${a.id===s.adoptedId?' / 镜头采用版':''}</option>`)).join('');}
 function preview(c){const rs=T.rows(c),e=T.ensure(c),index=Math.min(e.preview.index,rs.length-1),r=rs[index],total=rs.at(-1)?.end||0;return `<section class="ed-preview cm-panel"><div class="ed-preview-heading"><strong>整片预览 · <span id="ed-playing-title">${r?E(r.s.title)+' / 使用'+(index+1):'尚无使用片段'}</span></strong><span id="ed-playhead">${clock(r?(r.start+e.preview.time):0)} / ${clock(total)}</span></div><div class="ed-screen">${r?`<video id="ed-video" controls playsinline preload="metadata" src="${E(r.media?.url||'')}" aria-label="剪辑整片预览"></video><div id="ed-subtitle" class="ed-subtitle"></div>`:'<p>从候选媒体添加使用片段后，可播放整段。</p>'}</div><input id="ed-scrub" aria-label="整片预览时间" type="range" min="0" max="${total||1}" step="0.05" value="${r?r.start+e.preview.time:0}" ${!r?'disabled':''}><div class="ed-preview-actions">${B('从头连续播放','play-all','',!r?'disabled':'')}${B('播放选中片段','play-selected','',!r?'disabled':'')}${B('暂停','pause')}<small>单播放器顺序播放使用区间；不是已合成的整片MP4。</small></div><p class="ed-note">现有4秒视频均无声。原音静音/音量控制实际播放器；独立对白与配乐只保存设置，无音频或混音验证。</p></section>`;}
 function timeline(c){const rs=T.rows(c),e=T.ensure(c),covered=new Set(rs.map(r=>r.shotId)),omitted=M.production.shots(c.e).filter(s=>!covered.has(s.id));return `<section class="cm-panel ed-sequence"><div class="ed-section-title"><h3>独立剪辑播放顺序</h3><span>${rs.length}个使用片段 · ${num(rs.at(-1)?.end||0)}秒</span></div><p class="ed-note">移动此列表会更新整片播放顺序；不改镜头叙事编号或画布位置。同一候选可多次使用，各自裁切独立。</p><ol>${rs.map(r=>`<li class="${e.selectedId===r.id?'selected':''}" data-edit-row="${r.id}"><button class="ed-select" data-edit="select" data-id="${r.id}"><b>使用${r.index+1} · ${E(r.s?.title||'来源缺失')}</b><span>v${r.a?.version||'?'} · 媒体 ${num(r.in)}–${num(r.out)}秒 → 整片 ${num(r.start)}–${num(r.end)}秒</span></button><div>${B('↑','up',r.id,r.index===0?'disabled':'')}${B('↓','down',r.id,r.index===rs.length-1?'disabled':'')}${B('重复使用','duplicate',r.id)}${B('移出剪辑','remove',r.id)}</div></li>`).join('')||'<li>尚未添加可播放候选。</li>'}</ol><form data-edit-form="add"><label>添加候选使用片段<select name="source" aria-label="添加候选使用片段">${sourceOptions(c)}</select></label><button class="cm-button primary" ${!sourceOptions(c)?'disabled':''}>添加到末尾</button></form>${omitted.length?`<p class="ed-note">未纳入当前剪辑：${omitted.map(s=>E(s.title)).join('、')}。未生成/无真实文件的历史候选不会伪造媒体；交付只包含本时间线。</p>`:''}</section>`;}
 function editor(c){const r=current(c),e=T.ensure(c);if(!r)return `<aside class="cm-panel"><h3>先准备候选</h3>${link('返回逐镜生成',path(c,'motion','flow'),'cm-button primary')}</aside>`;return `<aside class="ed-inspector"><section class="cm-panel"><h3>使用${r.index+1} · ${E(r.s.title)}</h3><p>使用v${r.a.version} / 镜头${r.s.direction?.locked?'已锁定':'未锁定'}；这里只调整独立使用片段，不覆盖镜头采用版。</p><form data-edit-form="clip" data-id="${r.id}"><label>所用候选<select name="candidateId" aria-label="所用候选">${r.s.candidates.filter(a=>T.media(a)).map(a=>`<option value="${a.id}" ${a.id===r.candidateId?'selected':''}>v${a.version}${a.id===r.s.adoptedId?' · 镜头采用版':''} · ${T.media(a).duration}秒</option>`).join('')}</select></label><div class="ed-two"><label>入点（媒体秒）<input name="in" type="number" min="0" step="0.1" value="${r.in}" required></label><label>出点（媒体秒）<input name="out" type="number" min="0.1" step="0.1" value="${r.out}" required></label></div><button class="cm-button primary">保存候选与使用区间</button></form>${r.s.adoptedId!==r.candidateId?'<p class="ed-note">当前使用的是固定候选，不跟随镜头采用自动替换。人工审阅时请确认保留此版。</p>':''}${B('在逐镜工作台局部修正','source',r.shotId)}</section><section class="cm-panel"><h3>独立字幕</h3><form data-edit-form="subtitle" data-id="${r.id}"><label class="ed-check"><input type="checkbox" name="enabled" ${checked(r.subtitle.enabled)}>显示本片段字幕</label><label>字幕文案<textarea name="text" rows="2">${E(r.subtitle.text)}</textarea></label><label>字幕说话人<input name="speaker" value="${E(r.subtitle.speaker)}"></label><div class="ed-two"><label>显示开始（片段内秒）<input name="start" type="number" min="0" step="0.1" value="${r.subtitle.start}" required></label><label>显示结束（片段内秒）<input name="end" type="number" min="0.1" step="0.1" value="${r.subtitle.end}" required></label></div><button class="cm-button primary">只保存字幕</button></form><p class="ed-note">字幕独立于候选原片和配音文案；修改不回写漫画/镜头台词。</p></section><section class="cm-panel"><h3>原音与独立对白</h3><form data-edit-form="sound" data-id="${r.id}"><label class="ed-check"><input type="checkbox" name="muted" ${checked(r.audio.muted)}>静音原片声音</label><label>原片音量（0–100）<input type="number" name="volume" min="0" max="100" value="${r.audio.volume}"></label><label class="ed-check"><input type="checkbox" name="voiceEnabled" ${checked(r.voice.enabled)}>启用独立对白设定（未生成音频）</label><label>独立对白文案<textarea name="voiceText" rows="2">${E(r.voice.text)}</textarea></label><label>配音说话人<input name="voiceSpeaker" value="${E(r.voice.speaker)}"></label><label>独立对白音量设定<input type="number" name="voiceVolume" min="0" max="100" value="${r.voice.volume}"></label><button class="cm-button primary">保存声音设定</button></form><p class="ed-note">原片若有混合声音只能整体静音/调音量。本样例无声，不能据此验证对白、音乐或声画混音。</p></section><section class="cm-panel"><h3>整片配乐意图</h3><form data-edit-form="music"><label class="ed-check"><input type="checkbox" name="enabled" ${checked(e.music.enabled)}>启用配乐意图（无音频）</label><label>音乐说明<input name="name" value="${E(e.music.name)}"></label><label>配乐音量设定<input name="volume" type="number" min="0" max="100" value="${e.music.volume}"></label><button class="cm-button ghost">保存配乐设定</button></form></section></aside>`;}
 function issues(c){const list=T.issues(c);return `<section class="cm-panel ed-issues"><div class="ed-section-title"><h3>待处理与待确认 · ${list.length}项</h3><span>规则演示 + 人工审阅</span></div>${list.map(i=>`<article class="${i.state}"><strong>${E(i.title)} · ${i.state==='stale'?'原确认已过期':i.state==='blocked'?'规则未通过':'待人工确认'}</strong><p>整片 ${num(i.time)}秒 · 依据：${E(i.basis)}</p>${B('定位片段与时间','locate',i.clipId,`data-time="${i.time}"`)}${B('局部修正','fix',i.clipId)}</article>`).join('')||'<p>当前四类审阅均已人工确认，可创建冻结版本。不是AI自动质量保证。</p>'}</section>`;}
 function review(c){const r=current(c),e=T.ensure(c),list=T.issues(c);return `<aside class="ed-inspector"><section class="cm-panel"><h3>当前使用片段的审阅</h3>${r?`<p>使用${r.index+1} · ${E(r.s.title)} · v${r.a.version} · ${num(r.in)}–${num(r.out)}秒</p>${T.kinds.map(k=>{const issue=list.find(i=>i.clipId===r.id&&i.kind===k);return `<div class="ed-review-item"><strong>${T.labels[k]}</strong><small>${issue?E(issue.basis):'已人工确认当前依赖版本'}</small>${B(issue?'人工确认此项':'已确认','confirm',r.id,`data-kind="${k}" ${!issue||issue.state==='blocked'?'disabled':''}`)}</div>`;}).join('')}`:'<p>先添加使用片段。</p>'}</section><section class="cm-panel"><h3>冻结本次交付</h3><p>${e.clips.length}项使用片段 · ${num(T.rows(c).at(-1)?.end||0)}秒 · ${list.length}项待处理</p>${B('创建模拟视频交付','deliver','',list.length||!e.clips.length?'disabled':'')}<p class="ed-note">先确认，再冻结媒体版本、入出点、顺序、字幕与声音设定。只提供工程JSON清单；未合成MP4。</p></section>${history(c)}</aside>`;}
 function history(c){const ds=T.ensure(c).deliveries,legacy=c.e.deliveries||[];return `<section class="cm-panel"><h3>冻结交付版本 · ${ds.length}</h3>${ds.map((d,i)=>`<article class="ed-delivery"><strong>交付${ds.length-i} · ${d.duration}秒</strong><p>${E(new Date(d.createdAt).toLocaleString('zh-CN'))} · ${d.clips.length}项</p>${B('查看冻结版本','view-delivery',d.id)}${B('下载冻结工程清单 JSON','download',d.id)}</article>`).join('')||'<p>尚无第06轮交付。</p>'}${legacy.length?`<details><summary>保留此前历史交付 ${legacy.length}版</summary>${legacy.map(d=>`<p>${E(d.id)} ${B('下载旧快照 JSON','legacy-download',d.id)}</p>`).join('')}</details>`:''}</section>`;}
 function brief(c){return '<nav class="ed-brief" aria-label="整片使用顺序">'+T.rows(c).map(r=>B((r.index+1)+'. '+E(r.s.title)+' · v'+r.a.version+' / '+num(r.duration)+'秒','select',r.id)).join('')+'</nav>';}
 function page(c){const e=T.ensure(c),rev=c.e.stage==='review';e.preview.playing=false;return `<div class="ed-page"><header class="ed-header"><div><strong>剪辑、审阅与交付</strong><p>媒体与使用片段分开 · 独立剪辑播放顺序</p></div><nav>${link('① 剪辑与声音',path(c,'audio','flow'),'cm-button '+(!rev?'primary':'ghost'))}${link('② 审阅与交付',path(c,'review','flow'),'cm-button '+(rev?'primary':'ghost'))}${link('逐镜工作台',path(c,'motion','flow'),'cm-button ghost')}${link('创作画布',path(c,'motion','canvas'),'cm-button ghost')}</nav></header><div class="ed-layout"><main>${brief(c)}${preview(c)}${timeline(c)}${rev?issues(c):''}</main>${rev?review(c):editor(c)}</div></div>`;}
 const oldStudio=C.studio;C.studio=c=>c.c.kind==='episode'&&c.e.view!=='canvas'&&['audio','review'].includes(c.e.stage)?page(c):oldStudio(c);
 const oldCanvas=C.canvas;C.canvas=c=>{const html=oldCanvas(c);return c.c.kind==='episode'?html.replace('</header><div class="bc-groups">',`${link('剪辑与交付',path(c,'audio','flow'),'cm-button ghost')}</header><div class="bc-groups">`):html;};
 let pending=null,controller=null;
 const savePreview=(c,index,time)=>{const e=T.ensure(c);e.preview={index,time,playing:false};M.save();};
 function bind(c){const video=S.$('#ed-video');if(!video){controller=null;return;}const rs=T.rows(c),e=T.ensure(c);let index=Math.max(0,Math.min(e.preview.index,rs.length-1)),loading=false,lastSave=0;const scrub=S.$('#ed-scrub');
  const paint=()=>{const r=rs[index],local=Math.max(0,Math.min(r.duration,video.currentTime-r.media.offset-r.in)),t=r.start+local;S.$('#ed-playhead').textContent=clock(t)+' / '+clock(rs.at(-1).end);scrub.value=t;S.$('#ed-playing-title').textContent=r.s.title+' / 使用'+(index+1);const sub=S.$('#ed-subtitle');sub.textContent=r.subtitle.enabled&&local>=r.subtitle.start&&local<=r.subtitle.end?(r.subtitle.speaker==='未指定'?'':r.subtitle.speaker+'：')+r.subtitle.text:'';S.$$('[data-edit-row]').forEach(el=>el.classList.toggle('playing',el.dataset.editRow===r.id));if(Date.now()-lastSave>800){savePreview(c,index,local);lastSave=Date.now();}return local;};
  function load(i,t=0,play=false){index=i;const r=rs[index];if(!r?.media)return;loading=true;video.muted=r.audio.muted;video.volume=r.audio.volume/100;const seek=()=>{video.currentTime=r.media.offset+r.in+Math.min(r.duration,Math.max(0,t));loading=false;paint();if(play)video.play().catch(()=>S.toast('浏览器未能开始播放，请点击播放器'));};if(video.getAttribute('src')!==r.media.url){video.onloadedmetadata=seek;video.src=r.media.url;video.load();}else if(video.readyState>=1)seek();else video.onloadedmetadata=seek;savePreview(c,index,t);}
  video.addEventListener('timeupdate',()=>{if(loading)return;const r=rs[index];if(video.currentTime<r.media.offset+r.in-.08){video.currentTime=r.media.offset+r.in;return;}paint();if(!video.paused&&video.currentTime>=r.media.offset+r.out-.04){if(index+1<rs.length)load(index+1,0,true);else{video.pause();savePreview(c,index,r.duration);}}});
  video.addEventListener('ended',()=>{if(!loading&&index+1<rs.length)load(index+1,0,true);});video.addEventListener('pause',()=>{if(!loading)savePreview(c,index,paint());});scrub.addEventListener('input',()=>{const time=Number(scrub.value),r=rs.find(r=>time<r.end)||rs.at(-1);video.pause();load(r.index,time-r.start,false);});
  controller={playAll:()=>load(0,0,true),playSelected:()=>load(Math.max(0,rs.findIndex(r=>r.id===e.selectedId)),0,true),pause:()=>video.pause(),locate:time=>{const r=rs.find(r=>time<r.end)||rs.at(-1);video.pause();load(r.index,time-r.start,false);}};load(index,e.preview.time||0,false);
 }
 document.addEventListener('click',ev=>{const el=ev.target.closest('[data-edit]');if(!el)return;ev.preventDefault();ev.stopImmediatePropagation();const c=C.ctx(),e=T.ensure(c),id=el.dataset.id,a=el.dataset.edit;let error;
  switch(a){case'play-all':controller?.playAll();return;case'play-selected':controller?.playSelected();return;case'pause':controller?.pause();return;
   case'select':e.selectedId=id;{const r=T.rows(c).find(r=>r.id===id);savePreview(c,r.index,0);}break;
   case'up':case'down':T.move(c,id,a==='up'?-1:1);savePreview(c,0,0);break;
   case'duplicate':T.duplicate(c,id);break;case'remove':T.remove(c,id);savePreview(c,0,0);break;
   case'source':if(!M.production.shots(c.e).some(s=>s.id===id)){S.toast('来源镜头已归档，请先在镜头方案中找回；既有剪辑媒体仍保留');return;}c.e.selectedShotId=id;M.save();S.route(path(c,'motion','flow'));return;
   case'locate':case'fix':e.selectedId=id;{const r=T.rows(c).find(r=>r.id===id);savePreview(c,r.index,Math.max(0,Number(el.dataset.time||r.start)-r.start));}if(a==='fix'){M.save();S.route(path(c,'audio','flow'));return;}break;
   case'confirm':error=T.confirm(c,id,el.dataset.kind);break;
   case'deliver':pending={project:c.p.id,episode:c.c.id,revision:e.revision};S.modal('确认冻结本次交付',`<p>${e.clips.length}项 · ${num(T.rows(c).at(-1)?.end||0)}秒。冻结当前候选、使用区间、字幕、声音设定及人工审阅依据。</p><p>交付类型：模拟视频交付 / 冻结工程清单。没有MP4合成、配音或混音。</p>`,B('取消，不创建交付','cancel')+B('确认冻结工程清单','freeze'));return;
   case'cancel':pending=null;S.close();return;
   case'freeze':if(!pending||pending.project!==c.p.id||pending.episode!==c.c.id||pending.revision!==e.revision){S.toast('剪辑已有变化，请重新确认交付');return;}{const r=T.freeze(c);error=r.error;if(!error){pending=null;S.close();S.toast('已冻结工程清单；不是MP4文件');}}break;
   case'view-delivery':{const d=e.deliveries.find(d=>d.id===id);S.modal('冻结交付 · '+d.id,`<p>${E(d.kind)} · ${d.duration}秒 · 修订${d.revision}</p>${d.clips.map((r,i)=>`<article><h3>使用${i+1} · ${E(r.title)} · v${r.candidate.version}</h3><p>媒体 ${num(r.in)}–${num(r.out)}秒 / 整片 ${num(r.start)}–${num(r.end)}秒</p><p>字幕：${r.subtitle.enabled?E(r.subtitle.text):'关闭'} / 原片${r.audio.muted?'静音':'音量'+r.audio.volume} / 独立对白${r.voice.enabled?'已设定（无音频）':'关闭'}</p></article>`).join('')}<p>${E(d.notice)}</p>`,B('关闭','cancel')+B('下载冻结工程清单 JSON','download',id),true);return;}
   case'download':{const d=e.deliveries.find(d=>d.id===id);if(d)S.download(d,'cimora-frozen-edit-'+id+'.json');return;}
   case'legacy-download':{const d=c.e.deliveries.find(d=>d.id===id);if(d)S.download(d,'cimora-legacy-snapshot-'+id+'.json');return;}
  }if(error){S.toast(error);return;}M.save();S.render();
 },true);
 document.addEventListener('submit',ev=>{const f=ev.target.closest('[data-edit-form]');if(!f)return;ev.preventDefault();ev.stopImmediatePropagation();const c=C.ctx(),fd=new FormData(f),v=Object.fromEntries(fd),id=f.dataset.id;let error;switch(f.dataset.editForm){case'add':{const [sid,aid]=(v.source||'').split('|'),x=T.add(c,sid,aid);error=x.error;break;}case'clip':error=T.update(c,id,{candidateId:v.candidateId,in:Number(v.in),out:Number(v.out)});break;case'subtitle':error=T.update(c,id,{subtitle:{enabled:!!v.enabled,text:v.text,speaker:v.speaker||'未指定',start:Number(v.start),end:Number(v.end)}});break;case'sound':error=T.update(c,id,{audio:{muted:!!v.muted,volume:Number(v.volume)},voice:{enabled:!!v.voiceEnabled,text:v.voiceText,speaker:v.voiceSpeaker||'未指定',volume:Number(v.voiceVolume)}});break;case'music':T.music(c,{enabled:!!v.enabled,name:v.name,volume:Number(v.volume)});break;}S.navigationSaved?.(f,!error);if(error){S.toast(error);return;}M.save();S.render();S.toast('已保存独立使用片段；旧候选与冻结交付不变');},true);
 const oldAfter=C.afterRender;C.afterRender=r=>{oldAfter(r);if(S.$('.ed-page'))bind(C.ctx());};
})();
